export type AuctionSetType = typeof AUCTION_SET_SEQUENCE[number];

export interface AuctionPlayerItem {
  id: string;
  listSrNo: number;
  setNumber: number;
  set: AuctionSetType;
  firstName: string;
  surname: string;
  name: string;
  country: string;
  countryCode: string;
  countryFlag: string;
  stateAssociation: string | null;
  dob: string | null;
  age: number;
  pdfSpecialism: 'BATTER' | 'ALL-ROUNDER' | 'WICKETKEEPER' | 'BOWLER';
  specialism: string;
  battingHand: BattingHand;
  bowlingStyle: string | null;
  bowlingArm?: BowlingArm;
  testCaps: number | null;
  odiCaps: number | null;
  t20Caps: number | null;
  iplMatches: number | null;
  previousIplTeam: string | null;
  ipl2025Matches: number | null;
  cappedStatus: 'Capped' | 'Uncapped' | 'Associate';
  reservePriceLakh: number;
  basePriceCr: number;
  isOverseas: boolean;
  role: PlayerRole;
  tier: PlayerTier;
  clubId?: string;
  salaryCr?: number;
  jerseyNumber?: number;
  form?: number;
  morale?: number;
  isGeneratedAttributes: boolean;
  ratings: {
    bat: number;
    bowl: number;
    pow?: number;
    tmp?: number;
    run?: number;
    cat?: number;
    pace?: number;
    ctrl?: number;
    dth?: number;
    fld?: number;
    tec?: number;
    dis?: number;
    exp?: number;
    fit?: number;
    vp?: number;
    vs?: number;
    agg?: number;
    sty?: number;
    var?: number;
    comp?: number;
  };
  statsKey?: {
    stat1Label: string;
    stat1Val: number;
    stat2Label: string;
    stat2Val: number;
    stat3Label: string;
    stat3Val: number;
    stat4Label: string;
    stat4Val: number;
  };
}

