export function resolveAuctionFranchise(idOrShort: string): AuctionClubReleaseData | undefined {
  const key = (idOrShort || '').trim().toUpperCase();
  return INITIAL_AUCTION_CLUBS.find(
    c =>
      c.teamId.toUpperCase() === key ||
      c.shortName.toUpperCase() === key ||
      (c.aliases && c.aliases.some(a => a.toUpperCase() === key))
  );
}

export function convertLakhToCrore(reservePriceLakh: number): number {
  return Number((reservePriceLakh / 100).toFixed(2));
}

export function getAuctionBidIncrementCr(currentBidCr: number): number {
  if (currentBidCr < 1.0) return 0.05; // ₹5 Lakh below ₹1 Cr
  if (currentBidCr < 2.0) return 0.10; // ₹10 Lakh from ₹1 Cr to ₹2 Cr
  if (currentBidCr < 5.0) return 0.20; // ₹20 Lakh from ₹2 Cr to ₹5 Cr
  return 0.25; // ₹25 Lakh at or above ₹5 Cr
}

export function getNextAuctionBidCr(currentBidCr: number, hasOpeningBid: boolean): number {
  if (!hasOpeningBid) {
    return Number(currentBidCr.toFixed(2));
  }
  const inc = getAuctionBidIncrementCr(currentBidCr);
  return Number((currentBidCr + inc).toFixed(2));
}

export function formatAuctionPriceCr(amountCr: number): string {
  if (amountCr < 1.0) {
    return `${amountCr.toFixed(2)} cr (${Math.round(amountCr * 100)}L)`;
  }
  return `${amountCr.toFixed(2)} cr`;
}

export interface FranchiseBidEligibilityInput {
  franchiseShort: string;
  currentBidderShort: string | null;
  lotStatus: 'bidding' | 'sold' | 'unsold';
  nextBidCr: number;
  purseCr: number;
  squadCount: number;
  overseasCount: number;
  isOverseasLot: boolean;
  maxSquadSize?: number;
  maxOverseasSize?: number;
}

export function canFranchiseBidOnLot(input: FranchiseBidEligibilityInput): {
  allowed: boolean;
  reason?: string;
} {
  const maxSquad = input.maxSquadSize ?? 25;
  const maxOverseas = input.maxOverseasSize ?? 8;

  if (input.lotStatus !== 'bidding') {
    return { allowed: false, reason: 'LOT CLOSED' };
  }
  if (input.currentBidderShort && input.currentBidderShort === input.franchiseShort) {
    return { allowed: false, reason: 'LEADING BIDDER' };
  }
  if (input.squadCount >= maxSquad) {
    return { allowed: false, reason: `SQUAD FULL (${maxSquad}/${maxSquad})` };
  }
  if (input.isOverseasLot && input.overseasCount >= maxOverseas) {
    return { allowed: false, reason: `OVERSEAS FULL (${maxOverseas}/${maxOverseas})` };
  }
  if (input.purseCr < input.nextBidCr) {
    return { allowed: false, reason: 'INSUFFICIENT PURSE' };
  }
  return { allowed: true };
}

export function computeAiMaxValuationCr(lot: AuctionPlayerItem): number {
  const primarySkill =
    lot.pdfSpecialism === 'BOWLER'
      ? lot.ratings.bowl
      : lot.pdfSpecialism === 'ALL-ROUNDER'
      ? Math.round((lot.ratings.bat + lot.ratings.bowl) / 2 + 4)
      : lot.ratings.bat;

  const skillExcess = Math.max(0, primarySkill - 70);
  const cappedMultiplier = lot.cappedStatus === 'Capped' ? 1.25 : 0.65;
  const iplBonus = Math.min(2.5, ((lot.iplMatches ?? 0) / 40) * 1.2);
  const rawMax = lot.basePriceCr + (skillExcess * 0.32 * cappedMultiplier) + iplBonus;
  // Deterministic small offset from listSrNo so valuations vary naturally without randomness bugs
  const deterministicVariance = ((lot.listSrNo * 17) % 9 - 4) * 0.15;
  const capLimit = lot.cappedStatus === 'Uncapped' ? Math.min(6.5, rawMax + deterministicVariance) : Math.min(18.5, rawMax + deterministicVariance);
  return Math.max(lot.basePriceCr, Number(capLimit.toFixed(2)));
}

export interface AiTeamSnapshot {
  shortName: string;
  teamName: string;
  primaryColor: string;
  purseCr: number;
  squadCount: number;
  overseasCount: number;
}

export function isOverseasPlayer(player: { isOverseas?: boolean; country?: string }): boolean {
  if (!player) return false;
  if (player.isOverseas === true) return true;
  if (player.country) {
    const c = player.country.trim().toLowerCase();
    if (c === 'india' || c === 'ind') return false;
    return true;
  }
  return false;
}

export function evaluateAiCounterBid(params: {
  lot: AuctionPlayerItem;
  currentBidCr: number;
  currentBidderShort: string | null;
  userTeamShort: string;
  aiTeams: AiTeamSnapshot[];
}): { teamShort: string; teamName: string; teamColor: string; amountCr: number } | null {
  const { lot, currentBidCr, currentBidderShort, userTeamShort, aiTeams } = params;
  const hasOpeningBid = currentBidderShort !== null;
  const nextBidCr = getNextAuctionBidCr(currentBidCr, hasOpeningBid);
  const maxValCr = computeAiMaxValuationCr(lot);

  if (nextBidCr > maxValCr) {
    return null;
  }

  const eligibleAi = aiTeams.filter(t => {
    if (t.shortName === userTeamShort) return false;
    return canFranchiseBidOnLot({
      franchiseShort: t.shortName,
      currentBidderShort,
      lotStatus: 'bidding',
      nextBidCr,
      purseCr: t.purseCr,
      squadCount: t.squadCount,
      overseasCount: t.overseasCount,
      isOverseasLot: isOverseasPlayer(lot)
    }).allowed;
  });

  if (eligibleAi.length === 0) return null;

  // Prefer previous 2025 IPL franchise if eligible, otherwise pick deterministically by purse + lot index
  const prevClub = lot.previousIplTeam ? resolveAuctionFranchise(lot.previousIplTeam) : undefined;
  const preferred = prevClub ? eligibleAi.find(c => c.shortName === prevClub.shortName) : undefined;
  const chosen =
    preferred && (lot.listSrNo + Math.round(nextBidCr * 20)) % 3 !== 0
      ? preferred
      : eligibleAi[(lot.listSrNo + Math.round(nextBidCr * 100)) % eligibleAi.length];

  return {
    teamShort: chosen.shortName,
    teamName: chosen.teamName,
    teamColor: chosen.primaryColor,
    amountCr: nextBidCr
  };
}

export function settleAuctionLotAmongAi(params: {
  lot: AuctionPlayerItem;
  startingBidCr: number;
  startingBidderShort: string | null;
  userTeamShort: string;
  aiTeams: AiTeamSnapshot[];
}): {
  status: 'sold' | 'unsold';
  buyerTeamShort?: string;
  buyerTeamName?: string;
  buyerTeamColor?: string;
  finalPriceCr?: number;
  bids: { teamShort: string; teamColor: string; amountCr: number }[];
} {
  const { lot, startingBidCr, startingBidderShort, userTeamShort, aiTeams } = params;
  const bids: { teamShort: string; teamColor: string; amountCr: number }[] = [];
  let curBid = startingBidCr;
  let curBidder = startingBidderShort;

  // If no one has bid yet, determine whether AI opens bidding on this lot
  if (!curBidder) {
    const primarySkill = Math.max(lot.ratings.bat, lot.ratings.bowl);
    // Uncapped depth lots have a realistic chance of going unsold if rating is modest
    const shouldAnyAiOpen =
      lot.cappedStatus === 'Capped'
        ? primarySkill >= 72 || lot.listSrNo % 3 !== 0
        : primarySkill >= 73 || (lot.iplMatches ?? 0) >= 5 || lot.listSrNo % 2 === 0;
    if (!shouldAnyAiOpen) {
      return { status: 'unsold', bids: [] };
    }
  }

  let safetySteps = 0;
  while (safetySteps < 40) {
    safetySteps += 1;
    const counter = evaluateAiCounterBid({
      lot,
      currentBidCr: curBid,
      currentBidderShort: curBidder,
      userTeamShort,
      aiTeams
    });
    if (!counter) break;
    curBid = counter.amountCr;
    curBidder = counter.teamShort;
    bids.push({
      teamShort: counter.teamShort,
      teamColor: counter.teamColor,
      amountCr: counter.amountCr
    });
    // Stop early if only one AI wants the lot at base price or near valuation
    if ((lot.listSrNo + safetySteps) % 3 === 0 && curBid >= lot.basePriceCr) {
      break;
    }
  }

  if (!curBidder) {
    return { status: 'unsold', bids: [] };
  }

  const winnerAi = aiTeams.find(t => t.shortName === curBidder) || resolveAuctionFranchise(curBidder);
  return {
    status: 'sold',
    buyerTeamShort: curBidder,
    buyerTeamName: winnerAi ? winnerAi.teamName : `${curBidder} Franchise`,
    buyerTeamColor: winnerAi ? winnerAi.primaryColor : '#0057b8',
    finalPriceCr: curBid,
    bids
  };
}

