export const AUCTION_SETS_META: AuctionSetMeta[] = AUCTION_SET_SEQUENCE.map((setId, idx) => {
  const setPlayers = AUCTION_PLAYERS_2026.filter(p => p.set === setId);
  const setNumber = setPlayers[0]?.setNumber ?? (idx + 1);
  const prefixMatch = setId.match(/^([A-Z]+)(\d+)$/);
  const prefix = prefixMatch ? prefixMatch[1] : 'BA';
  const numStr = prefixMatch ? prefixMatch[2] : '1';
  const categoryMap: Record<string, string> = {
    BA: 'Capped Batters',
    AL: 'Capped All-Rounders',
    WK: 'Capped Wicketkeepers',
    FA: 'Capped Fast Bowlers',
    SP: 'Capped Spinners',
    UBA: 'Uncapped Batters',
    UAL: 'Uncapped All-Rounders',
    UWK: 'Uncapped Wicketkeepers',
    UFA: 'Uncapped Fast Bowlers',
    USP: 'Uncapped Spinners'
  };
  const categoryLabel = `${categoryMap[prefix] || prefix} ${numStr}`;
  const isUncappedSet = prefix.startsWith('U');
  const lotsCount = setPlayers.length;
  return {
    id: setId,
    setNumber,
    name: `SET ${setNumber} · ${setId}`,
    categoryLabel,
    isUncappedSet,
    quote: `Set ${setNumber} (${setId}) — ${categoryLabel}: ${lotsCount} official TATA IPL 2026 lots ready for the gavel.`,
    lotsCount
  };
});
